/* Reset & base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #f5a623;
  --accent-dark: #d48a1a;
  --secondary: #6c6c8a;
  --secondary-dark: #55556e;
  --error: #e74c3c;
  --focus: #ffd966;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  border: 2px solid var(--secondary);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 4px;
  color: var(--accent);
  letter-spacing: 0.5px;
}

.subtitle {
  font-size: 0.95rem;
  color: #b0b0c8;
  margin-bottom: 20px;
}

/* Form fields */
.field {
  margin-bottom: 16px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
  font-size: 1rem;
}

input[type="number"] {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: var(--font);
  border: 2px solid var(--secondary);
  border-radius: 8px;
  background: #1e1e2f;
  color: var(--text);
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]:hover {
  border-color: var(--accent);
}

input[type="number"]:focus-visible {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 217, 102, 0.4);
}

input[type="number"]::placeholder {
  color: #6c6c8a;
}

/* Buttons */
.actions {
  display: flex;
  gap: 12px;
  margin-top: 20px;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  flex: 1 1 auto;
  min-width: 120px;
}

.btn.primary {
  background: var(--accent);
  color: #1e1e2f;
}

.btn.primary:hover {
  background: var(--accent-dark);
}

.btn.primary:active {
  transform: scale(0.97);
}

.btn.secondary {
  background: var(--secondary);
  color: var(--text);
}

.btn.secondary:hover {
  background: var(--secondary-dark);
}

.btn.secondary:active {
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* Result */
.result {
  margin-top: 20px;
  padding: 16px;
  background: #1e1e2f;
  border-radius: 8px;
  border: 2px dashed var(--secondary);
  font-size: 1.1rem;
}

.result p {
  margin-bottom: 4px;
}

.result p:last-child {
  margin-bottom: 0;
}

#litres-output, #cost-output {
  font-weight: 600;
}

#litres-output {
  color: var(--accent);
}

#cost-output {
  color: #7ed321;
}

/* Error */
.error {
  margin-top: 12px;
  color: var(--error);
  font-weight: 600;
  font-size: 0.95rem;
}

/* Pixel art decoration */
.pixel-art {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  width: 60px;
  margin: 20px auto 0;
  opacity: 0.6;
}

.pixel {
  aspect-ratio: 1;
  background: var(--accent);
  border-radius: 2px;
}

.pixel:nth-child(2),
.pixel:nth-child(4),
.pixel:nth-child(6),
.pixel:nth-child(8) {
  background: var(--secondary);
}

/* Responsive */
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.3rem; }
  .actions { flex-direction: column; }
  .btn { width: 100%; }
}

document.addEventListener('DOMContentLoaded', function () {
  var form = document.getElementById('fuel-form');
  var distanceInput = document.getElementById('distance');
  var consumptionInput = document.getElementById('consumption');
  var priceInput = document.getElementById('price');
  var litresOutput = document.getElementById('litres-output');
  var costOutput = document.getElementById('cost-output');
  var errorEl = document.getElementById('error');
  var resetBtn = document.getElementById('reset-btn');

  function showError(msg) {
    errorEl.textContent = msg;
    errorEl.hidden = false;
  }

  function clearError() {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }

  function calculate() {
    clearError();
    var distance = parseFloat(distanceInput.value);
    var consumption = parseFloat(consumptionInput.value);
    var price = parseFloat(priceInput.value);

    if (isNaN(distance) || isNaN(consumption) || isNaN(price)) {
      showError('Please enter valid numbers for all fields.');
      litresOutput.textContent = 'Litres needed: —';
      costOutput.textContent = 'Total cost: —';
      return;
    }

    if (distance < 0 || consumption < 0 || price < 0) {
      showError('Values cannot be negative.');
      litresOutput.textContent = 'Litres needed: —';
      costOutput.textContent = 'Total cost: —';
      return;
    }

    var litres = (distance / 100) * consumption;
    var cost = litres * price;

    litresOutput.textContent = 'Litres needed: ' + litres.toFixed(2) + ' L';
    costOutput.textContent = 'Total cost: $' + cost.toFixed(2);
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    calculate();
  });

  resetBtn.addEventListener('click', function () {
    form.reset();
    clearError();
    litresOutput.textContent = 'Litres needed: —';
    costOutput.textContent = 'Total cost: —';
    distanceInput.focus();
  });
});
